import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../../src/app.mjs'

// Fake of the downstream pricing service (priceOf(sku) -> euros).
const prices = { apple: 10, pear: 2.5, gold: 60, odd: 33.33 }
const pricing = { async priceOf(sku) { return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const call = async (method, path, body, raw) => {
  const res = await fetch(base + path, {
    method,
    headers: body !== undefined || raw !== undefined ? { 'content-type': 'application/json' } : {},
    body: raw ?? (body === undefined ? undefined : JSON.stringify(body)),
  })
  return { status: res.status, type: res.headers.get('content-type'), body: await res.json() }
}
const post = (items) => call('POST', '/orders', { items })

test('POST /orders creates an order: 201, json, sequential string id, echoed items, total', async () => {
  const items = [{ sku: 'apple', qty: 2 }, { sku: 'pear', qty: 4 }]
  const r = await post(items)
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(Object.keys(r.body), ['id', 'items', 'total'])
  assert.equal(typeof r.body.id, 'string')
  assert.deepEqual(r.body.items, items)
  assert.equal(r.body.total, 30)
})

test('POST /orders ids increment per created order', async () => {
  const a = await post([{ sku: 'apple', qty: 1 }])
  const b = await post([{ sku: 'apple', qty: 1 }])
  assert.equal(Number(b.body.id), Number(a.body.id) + 1)
})

test('POST /orders total of exactly 100 gets no discount', async () => {
  assert.equal((await post([{ sku: 'apple', qty: 10 }])).body.total, 100)
})

test('POST /orders total above 100 gets 10% off', async () => {
  assert.equal((await post([{ sku: 'apple', qty: 11 }])).body.total, 99) // 110 -> 99
})

test('POST /orders total is floored, not rounded', async () => {
  assert.equal((await post([{ sku: 'odd', qty: 1 }])).body.total, 33) // 33.33
  assert.equal((await post([{ sku: 'pear', qty: 3 }])).body.total, 7) // 7.5
  // 60*2=120 -> 108 ; 60*3 + 0.5 -> 180.5 -> 162.45 -> 162
  assert.equal((await post([{ sku: 'gold', qty: 3 }, { sku: 'pear', qty: 0.2 }])).body.total, 162)
})

test('POST /orders sums multiple items before discounting', async () => {
  assert.equal((await post([{ sku: 'gold', qty: 1 }, { sku: 'gold', qty: 1 }])).body.total, 108)
})

test('POST /orders with an unpriced sku yields total null (NaN serialised)', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — unknown price makes total NaN, which JSON renders as null, yet the order is still created with 201.
  const r = await post([{ sku: 'nope', qty: 1 }])
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

test('POST /orders with a missing qty yields total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — qty is not validated.
  const r = await post([{ sku: 'apple' }])
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

test('POST /orders negative qty is accepted', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — negative quantities yield a negative total.
  const r = await post([{ sku: 'apple', qty: -1 }])
  assert.equal(r.status, 201)
  assert.equal(r.body.total, -10)
})

for (const [name, send] of [
  ['no items key', () => call('POST', '/orders', {})],
  ['empty body', () => call('POST', '/orders', undefined, '')],
  ['items empty array', () => post([])],
  ['items not an array', () => call('POST', '/orders', { items: 'apple' })],
  ['invalid JSON', () => call('POST', '/orders', undefined, '{nope')],
  ['JSON null', () => call('POST', '/orders', undefined, 'null')],
]) {
  test(`POST /orders 400 for ${name}`, async () => {
    const r = await send()
    assert.equal(r.status, 400)
    assert.equal(r.type, 'application/json')
    assert.deepEqual(r.body, { error: 'items required' })
  })
}

test('GET /orders/{id} returns a previously created order', async () => {
  const created = await post([{ sku: 'apple', qty: 2 }])
  const r = await call('GET', `/orders/${created.body.id}`)
  assert.equal(r.status, 200)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, created.body)
})

test('GET /orders/{id} for an unknown id answers 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200 instead of 404.
  const r = await call('GET', '/orders/does-not-exist')
  assert.equal(r.status, 200)
  assert.deepEqual(r.body, { error: 'not found' })
})

for (const [method, path] of [
  ['GET', '/orders'],
  ['GET', '/'],
  ['GET', '/orders/'],
  ['GET', '/orders/1/extra'],
  ['POST', '/orders/1'],
  ['PUT', '/orders/1'],
  ['DELETE', '/orders/1'],
  ['PUT', '/orders'],
  ['GET', '/unknown'],
]) {
  test(`${method} ${path} is 404 no route`, async () => {
    const r = await call(method, path)
    assert.equal(r.status, 404)
    assert.equal(r.type, 'application/json')
    assert.deepEqual(r.body, { error: 'no route' })
  })
}

test('query string is ignored for routing', async () => {
  const created = await post([{ sku: 'pear', qty: 2 }])
  const r = await call('GET', `/orders/${created.body.id}?x=1`)
  assert.deepEqual(r.body, created.body)
})
EOF
